questions.answer:
要覆盖的类型分五类：①基本类型（直接返回，注意 undefined/null/symbol/bigint）；②可序列化对象（Object/Array，递归）；③特殊内建对象（Date、RegExp、Map、Set、Error、ArrayBuffer/TypedArray）；④函数（通常不深拷贝，直接返回引用，因为无法复制闭包）；⑤循环引用（用 WeakMap 缓存映射）。
实现骨架：
```js
function deepClone(v, map = new WeakMap()) {
  if (v === null || typeof v !== 'object') return v;      // 基本类型 + 函数
  if (map.has(v)) return map.get(v);                       // 循环引用
  if (v instanceof Date) return new Date(v);
  if (v instanceof RegExp) return new RegExp(v.source, v.flags);
  if (v instanceof Map) {
    const m = new Map(); map.set(v, m);
    v.forEach((val, k) => m.set(deepClone(k, map), deepClone(val, map)));
    return m;
  }
  if (v instanceof Set) {
    const s = new Set(); map.set(v, s);
    v.forEach(val => s.add(deepClone(val, map)));
    return s;
  }
  const cloned = Object.create(Object.getPrototypeOf(v));  // 保留原型
  map.set(v, cloned);
  for (const k of Reflect.ownKeys(v)) {                    // 含 Symbol 键
    const d = Object.getOwnPropertyDescriptor(v, k);
    if (d && 'value' in d) d.value = deepClone(d.value, map);
    Object.defineProperty(cloned, k, d);
  }
  return cloned;
}
```
要点：用 Reflect.ownKeys 而非 for...in（后者会遍历原型链且漏 Symbol 键）；用 getOwnPropertyDescriptor 保留不可枚举/访问器属性；WeakMap 而非 Map 防止内存泄漏。工程上更推荐 structuredClone（原生，支持循环引用，但不支持函数与原型链）或 lodash.cloneDeep。

