questions.answer:
发布订阅（EventBus / Pub-Sub）核心方法：
①on(eventName, handler)——订阅：把回调存入事件对应数组（支持同一事件多回调）。
②emit(eventName, ...args)——发布：取出该事件所有回调并依次执行（可支持一次性 once）。
③off(eventName, handler)——取消订阅：移除指定回调；不传 handler 则清空该事件全部回调。
④once(eventName, handler)——只执行一次：包装成一次性回调，触发后自动 off。
⑤（可选）offAll / clear——清空所有事件；listenerCount——查看某事件订阅数量；has——是否订阅。
实现（Map 版，推荐）：
class EventBus {
  constructor(){ this.events = new Map(); }
  on(name, fn){
    if (typeof fn !== 'function') throw new TypeError('handler must be function');
    if (!this.events.has(name)) this.events.set(name, []);
    this.events.get(name).push(fn);
    return () => this.off(name, fn);        // 返回取消订阅函数（便于清理）
  }
  once(name, fn){
    const wrapper = (...args) => { this.off(name, wrapper); fn.apply(this, args); };
    wrapper._origin = fn;                    // 便于 off 用原函数反查
    return this.on(name, wrapper);
  }
  off(name, fn){
    const list = this.events.get(name);
    if (!list) return this;
    if (!fn) { this.events.delete(name); return this; }
    const idx = list.findIndex(f => f === fn || f._origin === fn);
    if (idx > -1) list.splice(idx, 1);
    if (list.length === 0) this.events.delete(name);
    return this;
  }
  emit(name, ...args){
    const list = this.events.get(name);
    if (!list || list.length === 0) return false;
    [...list].forEach(fn => { try { fn(...args); } catch(e){ console.error(e); } });
    return true;
  }
  clear(){ this.events.clear(); }
  listenerCount(name){ return (this.events.get(name) || []).length; }
}
对象字面量精简版（面试手写常考）：
const bus = {
  cbs: {},
  on(ev, fn){ (this.cbs[ev] = this.cbs[ev] || []).push(fn); },
  emit(ev, ...a){ (this.cbs[ev] || []).forEach(f => f(...a)); },
  off(ev, fn){ this.cbs[ev] = (this.cbs[ev] || []).filter(f => f !== fn); }
};
