```js
// 防抖：停止触发 wait 后执行
function debounce(fn, wait = 300, immediate = false) {
  let timer = null;
  const deb = function (...args) {
    if (timer) clearTimeout(timer);
    if (immediate) {
      const first = !timer;
      timer = setTimeout(() => { timer = null; }, wait);
      if (first) fn.apply(this, args);
    } else {
      timer = setTimeout(() => { timer = null; fn.apply(this, args); }, wait);
    }
  };
  deb.cancel = () => { clearTimeout(timer); timer = null; };
  return deb;
}
// 节流：每 wait 最多一次（时间戳 + 定时器，保证末次也执行）
function throttle(fn, wait = 300) {
  let last = 0, timer = null;
  return function (...args) {
    const now = Date.now(), remain = wait - (now - last);
    if (remain <= 0) { last = now; fn.apply(this, args); }
    else if (!timer) {
      timer = setTimeout(() => { last = Date.now(); timer = null; fn.apply(this, args); }, remain);
    }
  };
}
// 深拷贝：见 WeakMap + 循环引用 + 特殊类型
// Promise 核心：状态机 + then 链 + 微任务
class MyPromise {
  static PENDING = 0; static FULFILLED = 1; static REJECTED = 2;
  constructor(executor) {
    this.state = 0; this.value = undefined; this.cbs = [];
    const resolve = v => this.#settle(1, v);
    const reject  = e => this.#settle(2, e);
    try { executor(resolve, reject); } catch (e) { reject(e); }
  }
  #settle(state, v) {
    if (this.state !== 0 || (v && (typeof v === 'object' || typeof v === 'function') &&
        (this.state = 0, v === this))) return;
    if (v instanceof MyPromise) return v.then(x => this.#settle(1, x), e => this.#settle(2, e));
    this.state = state; this.value = v;
    queueMicrotask(() => this.cbs.forEach(cb => this.#run(cb)));
  }
  #run({ onF, onR, resolve, reject }) {
    const cb = this.state === 1 ? onF : onR;
    if (typeof cb !== 'function') return this.state === 1 ? resolve(this.value) : reject(this.value);
    try { resolve(cb(this.value)); } catch (e) { reject(e); }
  }
  then(onF, onR) {
    return new MyPromise((resolve, reject) => {
      const cb = { onF, onR, resolve, reject };
      this.state === 0 ? this.cbs.push(cb) : queueMicrotask(() => this.#run(cb));
    });
  }
  catch(onR) { return this.then(null, onR); }
}
// call / apply / bind
Function.prototype.myCall = function (ctx, ...args) {
  ctx = ctx == null ? globalThis : Object(ctx);
  const key = Symbol('fn'); ctx[key] = this;
  const r = ctx[key](...args); delete ctx[key]; return r;
};
Function.prototype.myApply = function (ctx, args = []) { return this.myCall(ctx, ...args); };
Function.prototype.myBind = function (ctx, ...preset) {
  const fn = this;
  function bound(...rest) {
    return fn.apply(this instanceof bound ? this : ctx, [...preset, ...rest]);
  }
  bound.prototype = Object.create(fn.prototype || null);
  return bound;
};
```
深拷贝要点：`WeakMap` 处理循环引用、保留原型、处理 Date/RegExp/Map/Set、用 `Reflect.ownKeys` 覆盖 Symbol 键。防抖与节流的区别要能一句话说清：防抖是"最后一次触发后延迟执行"，节流是"固定频率执行"；应用场景（搜索联想用防抖，滚动/resize 用节流）。

