questions.answer:
```js
// 1) 全部成功才继续（任一失败即失败）
Promise.all([req1(), req2(), req3()])
  .then(([r1, r2, r3]) => callback(r1, r2, r3))
  .catch(err => console.error('有请求失败', err));

// 2) 允许部分失败，等全部"有结果"（推荐用于统计/聚合）
Promise.allSettled([req1(), req2(), req3()]).then(results => {
  const ok = results.filter(r => r.status === 'fulfilled').map(r => r.value);
  const fail = results.filter(r => r.status === 'rejected').map(r => r.reason);
  callback(ok, fail);
});

// 3) 不依赖 Promise API 的手写实现（并发发出，计数到 3 再回调）
function allDone(tasks, done) {
  const res = new Array(tasks.length);
  let count = 0, finished = false;
  tasks.forEach((t, i) => {
    t().then(v => { res[i] = v; })
      .catch(e => { res[i] = e; })  // 按需决定失败处理
      .finally(() => {
        if (!finished && ++count === tasks.length) { finished = true; done(res); }
      });
  });
}
